SELECT CASE WHEN p.cost >= 670 THEN 'high' WHEN p.cost >= 320 THEN 'mid' ELSE 'low' END AS cost_bucket, MONTH(p.launch_date) AS launch_month, SUM(oi.unit_price * oi.quantity) AS revenue FROM order_items oi INNER JOIN orders o ON o.id = oi.order_id FULL OUTER JOIN products p ON oi.product_id = p.id GROUP BY CASE WHEN p.cost >= 670 THEN 'high' WHEN p.cost >= 320 THEN 'mid' ELSE 'low' END, MONTH(p.launch_date)
